describe('mongoObjectToParseObject - atomic values', () => {
  const schema = schemaWith();

  it('returns a string unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', 'hello', schema)).toBe('hello');
  });

  it('returns a number unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', 42.5, schema)).toBe(42.5);
  });

  it('returns a boolean unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', false, schema)).toBe(false);
    expect(mongoObjectToParseObject('TestClass', true, schema)).toBe(true);
  });

  it('returns undefined unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', undefined, schema)).toBeUndefined();
  });

  it('throws for a symbol value', () => {
    expect(() => mongoObjectToParseObject('TestClass', Symbol('nope'), schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
  });

  it('throws for a function value', () => {
    expect(() => mongoObjectToParseObject('TestClass', () => {}, schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
  });

  it('throws for a bigint value as an unknown js type', () => {
    expect(() => mongoObjectToParseObject('TestClass', BigInt(10), schema)).toThrow(
      'unknown js type'
    );
  });
});

describe('mongoObjectToParseObject - null, arrays and bson scalars', () => {
  const schema = schemaWith();

  it('returns null for a null object', () => {
    expect(mongoObjectToParseObject('TestClass', null, schema)).toBeNull();
  });

  it('returns an empty array unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', [], schema)).toEqual([]);
  });

  it('maps arrays element by element', () => {
    expect(mongoObjectToParseObject('TestClass', [1, 'two', true, null], schema)).toEqual([
      1,
      'two',
      true,
      null,
    ]);
  });

  it('does not apply key transformations to objects inside arrays', () => {
    const value = [{ _id: 'abc', someKey: 1 }];
    expect(mongoObjectToParseObject('TestClass', value, schema)).toEqual([
      { _id: 'abc', someKey: 1 },
    ]);
  });

  it('encodes dates inside arrays', () => {
    const date = new Date('2021-03-04T05:06:07.089Z');
    expect(mongoObjectToParseObject('TestClass', [date], schema)).toEqual([
      { __type: 'Date', iso: '2021-03-04T05:06:07.089Z' },
    ]);
  });

  it('converts mongodb Long values inside arrays to numbers', () => {
    expect(mongoObjectToParseObject('TestClass', [mongodb.Long.fromNumber(1234)], schema)).toEqual([
      1234,
    ]);
  });

  it('encodes a top level Date like Parse._encode', () => {
    const date = new Date('2020-01-02T03:04:05.678Z');
    const result = mongoObjectToParseObject('TestClass', date, schema);
    expect(result).toEqual({ __type: 'Date', iso: '2020-01-02T03:04:05.678Z' });
    expect(result).toEqual(Parse._encode(date));
  });

  it('converts a mongodb Long to a number', () => {
    expect(mongoObjectToParseObject('TestClass', mongodb.Long.fromNumber(77), schema)).toBe(77);
  });

  it('extracts the value of a mongodb Double', () => {
    expect(mongoObjectToParseObject('TestClass', new mongodb.Double(3.25), schema)).toBe(3.25);
  });

  it('converts a mongodb Binary to a Bytes object', () => {
    const binary = new mongodb.Binary(Buffer.from('hello'));
    expect(mongoObjectToParseObject('TestClass', binary, schema)).toEqual({
      __type: 'Bytes',
      base64: Buffer.from('hello').toString('base64'),
    });
  });
});

describe('mongoObjectToParseObject - reserved field name conversions', () => {
  const schema = schemaWith();

  it('converts _id to objectId', () => {
    const result = mongoObjectToParseObject('TestClass', { _id: 'abc123' }, schema);
    expect(result).toEqual({ objectId: 'abc123' });
    expect(result._id).toBeUndefined();
  });

  it('stringifies an ObjectId _id', () => {
    const objectId = new mongodb.ObjectId();
    const result = mongoObjectToParseObject('TestClass', { _id: objectId }, schema);
    expect(result.objectId).toBe(objectId.toString());
  });

  it('converts _session_token to sessionToken', () => {
    expect(mongoObjectToParseObject('TestClass', { _session_token: 'r:123' }, schema)).toEqual({
      sessionToken: 'r:123',
    });
  });

  it('keeps _hashed_password as is', () => {
    expect(mongoObjectToParseObject('TestClass', { _hashed_password: 'hash' }, schema)).toEqual({
      _hashed_password: 'hash',
    });
  });

  it('drops the _acl field', () => {
    const result = mongoObjectToParseObject('TestClass', { _acl: { '*': { r: true } }, a: 1 }, schema);
    expect(result).toEqual({ a: 1 });
  });

  it.each([
    '_email_verify_token',
    '_perishable_token',
    '_perishable_token_expires_at',
    '_password_changed_at',
    '_tombstone',
    '_email_verify_token_expires_at',
    '_account_lockout_expires_at',
    '_failed_login_count',
  ])('passes the internal key %s through unchanged', key => {
    expect(mongoObjectToParseObject('TestClass', { [key]: 'value' }, schema)).toEqual({
      [key]: 'value',
    });
  });

  it('passes _password_history through unchanged', () => {
    const history = [{ password: 'x' }];
    expect(mongoObjectToParseObject('TestClass', { _password_history: history }, schema)).toEqual({
      _password_history: history,
    });
  });

  it.each([['createdAt'], ['_created_at']])('converts %s to an ISO createdAt string', key => {
    const result = mongoObjectToParseObject(
      'TestClass',
      { [key]: new Date('2022-05-06T07:08:09.010Z') },
      schema
    );
    expect(result).toEqual({ createdAt: '2022-05-06T07:08:09.010Z' });
  });

  it.each([['updatedAt'], ['_updated_at']])('converts %s to an ISO updatedAt string', key => {
    const result = mongoObjectToParseObject(
      'TestClass',
      { [key]: new Date('2022-05-06T07:08:09.010Z') },
      schema
    );
    expect(result).toEqual({ updatedAt: '2022-05-06T07:08:09.010Z' });
  });

  it.each([['lastUsed'], ['_last_used']])('converts %s to an ISO lastUsed string', key => {
    const result = mongoObjectToParseObject(
      'TestClass',
      { [key]: new Date('2019-11-12T13:14:15.016Z') },
      schema
    );
    expect(result).toEqual({ lastUsed: '2019-11-12T13:14:15.016Z' });
  });

  it.each([['timesUsed'], ['times_used']])('converts %s to timesUsed', key => {
    expect(mongoObjectToParseObject('TestClass', { [key]: 3 }, schema)).toEqual({ timesUsed: 3 });
  });

  it.each([['expiresAt'], ['_expiresAt']])('encodes %s as a Parse date', key => {
    const result = mongoObjectToParseObject(
      'TestClass',
      { [key]: new Date('2018-01-01T00:00:00.000Z') },
      schema
    );
    expect(result).toEqual({
      expiresAt: { __type: 'Date', iso: '2018-01-01T00:00:00.000Z' },
    });
  });

  it('drops an unrecognized reserved key and warns', () => {
    const result = mongoObjectToParseObject('TestClass', { _unknownReserved: 'x', a: 1 }, schema);
    expect(result).toEqual({ a: 1 });
    expect(fakeLogger.warn).toHaveBeenCalledWith(
      'transform.js',
      'Found an unexpected reserved key, dropping it.',
      'TestClass',
      '_unknownReserved'
    );
  });

  it('keeps the __type key', () => {
    expect(mongoObjectToParseObject('TestClass', { __type: 'Something' }, schema)).toEqual({
      __type: 'Something',
    });
  });

  it('recursively transforms nested objects for regular keys', () => {
    const result = mongoObjectToParseObject(
      'TestClass',
      {
        nested: {
          child: new Date('2017-02-03T04:05:06.007Z'),
          number: 5,
          deep: { flag: true },
        },
      },
      schema
    );
    expect(result).toEqual({
      nested: {
        child: { __type: 'Date', iso: '2017-02-03T04:05:06.007Z' },
        number: 5,
        deep: { flag: true },
      },
    });
  });
});

describe('mongoObjectToParseObject - permissions', () => {
  it('moves _rperm and _wperm into the result and removes them from the input', () => {
    const mongoObject = { _rperm: ['role:a'], _wperm: ['role:b'], name: 'x' };
    const result = mongoObjectToParseObject('TestClass', mongoObject, schemaWith());
    expect(result).toEqual({ _rperm: ['role:a'], _wperm: ['role:b'], name: 'x' });
    expect(mongoObject._rperm).toBeUndefined();
    expect(mongoObject._wperm).toBeUndefined();
  });

  it('defaults the missing permission array to an empty array', () => {
    const mongoObject = { _rperm: ['role:a'], name: 'x' };
    const result = mongoObjectToParseObject('TestClass', mongoObject, schemaWith());
    expect(result._rperm).toEqual(['role:a']);
    expect(result._wperm).toEqual([]);
  });

  it('defaults both permission arrays when only _wperm is present', () => {
    const mongoObject = { _wperm: ['*'] };
    const result = mongoObjectToParseObject('TestClass', mongoObject, schemaWith());
    expect(result._rperm).toEqual([]);
    expect(result._wperm).toEqual(['*']);
  });
});

describe('mongoObjectToParseObject - authData', () => {
  const authData = { facebook: { id: '1234' } };

  it('keeps authData for non-user classes', () => {
    const result = mongoObjectToParseObject('TestClass', { authData }, schemaWith());
    expect(result).toEqual({ authData });
  });

  it('drops authData for the _User class and warns', () => {
    const result = mongoObjectToParseObject('_User', { authData }, schemaWith());
    expect(result).toEqual({});
    expect(result.authData).toBeUndefined();
    expect(fakeLogger.warn).toHaveBeenCalledWith(
      'ignoring authData in _User as this key is reserved to be synthesized of `_auth_data_*` keys'
    );
  });

  it('synthesizes authData from a single _auth_data_ provider key on _User', () => {
    const result = mongoObjectToParseObject(
      '_User',
      { _auth_data_google: { id: 'g-1' } },
      schemaWith()
    );
    expect(result).toEqual({ authData: { google: { id: 'g-1' } } });
  });

  it('merges multiple auth data providers on _User', () => {
    const result = mongoObjectToParseObject(
      '_User',
      { _auth_data_google: { id: 'g-1' }, _auth_data_twitter: { id: 't-1' } },
      schemaWith()
    );
    expect(result).toEqual({
      authData: { google: { id: 'g-1' }, twitter: { id: 't-1' } },
    });
  });

  it('drops _auth_data_ keys for non-user classes', () => {
    const result = mongoObjectToParseObject('TestClass', { _auth_data_google: { id: 'g-1' } }, schemaWith());
    expect(result).toEqual({});
  });
});

