    );
    expect(result).toEqual({ createdAt: '2022-05-06T07:08:09.010Z' });
  });

  it.each([['updatedAt'], ['_updated_at']])('converts %s to an ISO updatedAt string', key => {
    const result = mongoObjectToParseObject(
      'TestClass',
      { [key]: new Date('2022-05-06T07:08:09.010Z') },
      schema
    );
    expect(result).toEqual({ updatedAt: '2022-05-06T07:08:09.010Z' });
  });

  it.each([['lastUsed'], ['_last_used']])('converts %s to an ISO lastUsed string', key => {
    const result = mongoObjectToParseObject(
      'TestClass',
      { [key]: new Date('2019-11-12T13:14:15.016Z') },
      schema
    );
    expect(result).toEqual({ lastUsed: '2019-11-12T13:14:15.016Z' });
  });

  it.each([['timesUsed'], ['times_used']])('converts %s to timesUsed', key => {
    expect(mongoObjectToParseObject('TestClass', { [key]: 3 }, schema)).toEqual({ timesUsed: 3 });
  });

  it.each([['expiresAt'], ['_expiresAt']])('encodes %s as a Parse date', key => {
    const result = mongoObjectToParseObject(
      'TestClass',
      { [key]: new Date('2018-01-01T00:00:00.000Z') },
      schema
    );
    expect(result).toEqual({
      expiresAt: { __type: 'Date', iso: '2018-01-01T00:00:00.000Z' },
    });
  });

  it('drops an unrecognized reserved key and warns', () => {
    const result = mongoObjectToParseObject('TestClass', { _unknownReserved: 'x', a: 1 }, schema);
    expect(result).toEqual({ a: 1 });
    expect(fakeLogger.warn).toHaveBeenCalledWith(
      'transform.js',
      'Found an unexpected reserved key, dropping it.',
      'TestClass',
      '_unknownReserved'
    );
  });

  it('keeps the __type key', () => {
    expect(mongoObjectToParseObject('TestClass', { __type: 'Something' }, schema)).toEqual({
      __type: 'Something',
    });
  });

  it('recursively transforms nested objects for regular keys', () => {
