describe('mongoObjectToParseObject - permissions', () => {
  it('moves _rperm and _wperm into the result and removes them from the input', () => {
    const mongoObject = { _rperm: ['role:a'], _wperm: ['role:b'], name: 'x' };
    const result = mongoObjectToParseObject('TestClass', mongoObject, schemaWith());
    expect(result).toEqual({ _rperm: ['role:a'], _wperm: ['role:b'], name: 'x' });
    expect(mongoObject._rperm).toBeUndefined();
    expect(mongoObject._wperm).toBeUndefined();
  });

  it('defaults the missing permission array to an empty array', () => {
    const mongoObject = { _rperm: ['role:a'], name: 'x' };
    const result = mongoObjectToParseObject('TestClass', mongoObject, schemaWith());
    expect(result._rperm).toEqual(['role:a']);
    expect(result._wperm).toEqual([]);
  });

  it('defaults both permission arrays when only _wperm is present', () => {
    const mongoObject = { _wperm: ['*'] };
    const result = mongoObjectToParseObject('TestClass', mongoObject, schemaWith());
    expect(result._rperm).toEqual([]);
    expect(result._wperm).toEqual(['*']);
  });
});

describe('mongoObjectToParseObject - authData', () => {
  const authData = { facebook: { id: '1234' } };

  it('keeps authData for non-user classes', () => {
    const result = mongoObjectToParseObject('TestClass', { authData }, schemaWith());
    expect(result).toEqual({ authData });
  });

  it('drops authData for the _User class and warns', () => {
    const result = mongoObjectToParseObject('_User', { authData }, schemaWith());
    expect(result).toEqual({});
    expect(result.authData).toBeUndefined();
    expect(fakeLogger.warn).toHaveBeenCalledWith(
      'ignoring authData in _User as this key is reserved to be synthesized of `_auth_data_*` keys'
    );
  });

  it('synthesizes authData from a single _auth_data_ provider key on _User', () => {
    const result = mongoObjectToParseObject(
      '_User',
      { _auth_data_google: { id: 'g-1' } },
      schemaWith()
    );
    expect(result).toEqual({ authData: { google: { id: 'g-1' } } });
  });

  it('merges multiple auth data providers on _User', () => {
    const result = mongoObjectToParseObject(
      '_User',
      { _auth_data_google: { id: 'g-1' }, _auth_data_twitter: { id: 't-1' } },
      schemaWith()
    );
    expect(result).toEqual({
      authData: { google: { id: 'g-1' }, twitter: { id: 't-1' } },
    });
  });

  it('drops _auth_data_ keys for non-user classes', () => {
    const result = mongoObjectToParseObject('TestClass', { _auth_data_google: { id: 'g-1' } }, schemaWith());
    expect(result).toEqual({});
  });
});

describe('mongoObjectToParseObject - pointers', () => {
  const pointerSchema = schemaWith({
    owner: { type: 'Pointer', targetClass: '_User' },
    when: { type: 'Date' },
  });

  it('converts a _p_ pointer column into a Pointer object', () => {
    const result = mongoObjectToParseObject('TestClass', { _p_owner: '_User$abc' }, pointerSchema);
    expect(result).toEqual({
      owner: { __type: 'Pointer', className: '_User', objectId: 'abc' },
    });
    expect(result._p_owner).toBeUndefined();
  });

  it('drops a pointer column that is not part of the schema and logs info', () => {
    const result = mongoObjectToParseObject('TestClass', { _p_missing: '_User$abc' }, pointerSchema);
    expect(result).toEqual({});
    expect(fakeLogger.info).toHaveBeenCalledWith(
      'transform.js',
      'Found a pointer column not in the schema, dropping it.',
      'TestClass',
      'missing'
    );
  });

  it('drops a pointer column whose schema type is not Pointer', () => {
    const result = mongoObjectToParseObject('TestClass', { _p_when: '_User$abc' }, pointerSchema);
    expect(result).toEqual({});
    expect(fakeLogger.info).toHaveBeenCalledWith(
      'transform.js',
      'Found a pointer in a non-pointer column, dropping it.',
      'TestClass',
      '_p_when'
    );
  });

  it('drops a null pointer value', () => {
    const result = mongoObjectToParseObject('TestClass', { _p_owner: null }, pointerSchema);
    expect(result).toEqual({});
  });

  it('throws when the pointer className does not match the schema targetClass', () => {
    expect(() => mongoObjectToParseObject('TestClass', { _p_owner: '_Role$abc' }, pointerSchema)).toThrow(
      'pointer to incorrect className'
    );
  });
});

describe('mongoObjectToParseObject - special column types', () => {
  it('converts a File column value', () => {
    const schema = schemaWith({ avatar: { type: 'File' } });
    const result = mongoObjectToParseObject('TestClass', { avatar: 'profile.png' }, schema);
    expect(result).toEqual({ avatar: { __type: 'File', name: 'profile.png' } });
  });

  it('leaves a File column value untouched when it is not a file database object', () => {
    const schema = schemaWith({ avatar: { type: 'File' } });
    const result = mongoObjectToParseObject('TestClass', { avatar: { name: 'x' } }, schema);
    expect(result).toEqual({ avatar: { name: 'x' } });
  });

  it('converts a GeoPoint column value', () => {
    const schema = schemaWith({ location: { type: 'GeoPoint' } });
    const result = mongoObjectToParseObject('TestClass', { location: [13.5, 52.25] }, schema);
    expect(result).toEqual({
      location: { __type: 'GeoPoint', latitude: 52.25, longitude: 13.5 },
    });
  });

  it('converts a Polygon column value', () => {
    const schema = schemaWith({ area: { type: 'Polygon' } });
    const polygon = {
      type: 'Polygon',
      coordinates: [
        [
          [13, 52],
          [14, 53],
          [15, 54],
          [13, 52],
        ],
      ],
    };
    const result = mongoObjectToParseObject('TestClass', { area: polygon }, schema);
    expect(result).toEqual({
      area: {
        __type: 'Polygon',
        coordinates: [
          [52, 13],
          [53, 14],
          [54, 15],
          [52, 13],
        ],
      },
    });
  });

  it('converts a Bytes column holding a mongodb Binary', () => {
    const schema = schemaWith({ data: { type: 'Bytes' } });
    const result = mongoObjectToParseObject(
      'TestClass',
      { data: new mongodb.Binary(Buffer.from('abc')) },
      schema
    );
    expect(result).toEqual({
      data: { __type: 'Bytes', base64: Buffer.from('abc').toString('base64') },
    });
  });

  it('converts a Bytes column holding a base64 string', () => {
    const schema = schemaWith({ data: { type: 'Bytes' } });
    const result = mongoObjectToParseObject('TestClass', { data: 'aGVsbG8=' }, schema);
    expect(result).toEqual({ data: { __type: 'Bytes', base64: 'aGVsbG8=' } });
  });

  it('does not convert a base64 looking string for a non-Bytes column', () => {
    const schema = schemaWith({ label: { type: 'String' } });
    const result = mongoObjectToParseObject('TestClass', { label: 'aGVsbG8=' }, schema);
    expect(result).toEqual({ label: 'aGVsbG8=' });
  });
});

describe('mongoObjectToParseObject - relation fields', () => {
  it('adds relation fields declared in the schema', () => {
    const schema = schemaWith({
      name: { type: 'String' },
      roles: { type: 'Relation', targetClass: '_Role' },
    });
    const result = mongoObjectToParseObject('TestClass', { name: 'x' }, schema);
    expect(result).toEqual({
      name: 'x',
      roles: { __type: 'Relation', className: '_Role' },
    });
  });

  it('overrides a stored value with the schema relation definition', () => {
    const schema = schemaWith({ friends: { type: 'Relation', targetClass: '_User' } });
    const result = mongoObjectToParseObject('TestClass', { friends: 'legacy' }, schema);
    expect(result).toEqual({ friends: { __type: 'Relation', className: '_User' } });
  });

  it('does not add relation fields when the schema declares none', () => {
    const schema = schemaWith({ name: { type: 'String' } });
    expect(mongoObjectToParseObject('TestClass', { name: 'x' }, schema)).toEqual({ name: 'x' });
  });
});
