      expect(restWriteArgs[3]).toEqual({ objectId: USER_ID });
      expect(restWriteArgs[4]).toBe(req.body);
      expect(restWriteArgs[5]).toBe(user);
      expect(restWriteArgs[6]).toBe(CONTEXT);
      expect(Auth.handleAuthDataValidation).toHaveBeenCalledWith(
