      const unexpected = new Parse.Error(Parse.Error.INTERNAL_SERVER_ERROR, 'db is down');

      Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: USER_ID }]);
      Auth.handleAuthDataValidation.mockResolvedValue({
        authData: { google: { id: 'google-2' } },
