      await expect(router.handleLogIn(req)).rejects.toBe(providerError);

      expect(Auth.findUsersWithAuthData).not.toHaveBeenCalled();
      expect(maybeRunTrigger).not.toHaveBeenCalled();
    });
  });

  describe('response filtering after login', () => {
    it('removes hidden properties from the re-fetched response', async () => {
      const user = makeUser();
      const req = makeReq();
      const router = makeRouter(user);
      rest.get.mockResolvedValue({
        results: [
          {
            objectId: USER_ID,
            username: 'alice',
            __type: 'Object',
            _private: 'hidden',
            $invalid: 'hidden',
          },
        ],
      });

      const result = await router.handleLogIn(req);

      expect(result.response).toEqual({
        objectId: USER_ID,
        username: 'alice',
        __type: 'Object',
        sessionToken: SESSION_TOKEN,
      });
      expect(result.response._private).toBeUndefined();
      expect(result.response.$invalid).toBeUndefined();
    });

    it('returns the full user for a master caller when the re-fetch returns no result', async () => {
      const user = makeUser({ _hidden: 'x', authData: { mfa: { id: 'secret' } } });
      const req = makeReq({ auth: { isMaster: true, isMaintenance: false } });
      const router = makeRouter(user);
      rest.get.mockResolvedValue({ results: [] });

      const result = await router.handleLogIn(req);

      expect(rest.get).toHaveBeenCalledWith(req.config, req.auth, '_User', USER_ID, {}, CONTEXT);
      expect(Auth.Auth).not.toHaveBeenCalled();
      expect(result.response).toBe(user);
      expect(result.response.username).toBe('alice');
      expect(result.response.authData).toEqual({ mfa: { id: 'secret' } });
      expect(result.response._hidden).toBeUndefined();
      expect(result.response.sessionToken).toBe(SESSION_TOKEN);
    });

    it('returns the full user for a maintenance caller when the re-fetch throws', async () => {
      const user = makeUser();
      const req = makeReq({ auth: { isMaster: false, isMaintenance: true } });
      const router = makeRouter(user);
      rest.get.mockRejectedValue(new Error('CLP denied'));

      const result = await router.handleLogIn(req);

      expect(rest.get).toHaveBeenCalledWith(req.config, req.auth, '_User', USER_ID, {}, CONTEXT);
      expect(Auth.Auth).not.toHaveBeenCalled();
      expect(result.response).toBe(user);
      expect(result.response.username).toBe('alice');
    });

    it('discloses only the objectId for a non-master caller when the re-fetch throws', async () => {
      const user = makeUser({ authData: { mfa: { recoveryCodes: ['secret-code'] } }, email: 'a@b.c' });
      const req = makeReq();
      const router = makeRouter(user);
      rest.get.mockRejectedValue(new Error('CLP denied'));

      const result = await router.handleLogIn(req);

      expect(result.response).toEqual({ objectId: USER_ID, sessionToken: SESSION_TOKEN });
      expect(result.response.username).toBeUndefined();
      expect(result.response.email).toBeUndefined();
      expect(result.response.authData).toBeUndefined();
    });

    it('discloses only the objectId for a non-master caller when the re-fetch has no results', async () => {
      const user = makeUser({ email: 'a@b.c' });
      const req = makeReq();
      const router = makeRouter(user);
      rest.get.mockResolvedValue({});

      const result = await router.handleLogIn(req);

      expect(result.response).toEqual({ objectId: USER_ID, sessionToken: SESSION_TOKEN });
      expect(result.response.email).toBeUndefined();
    });

    it('returns the re-fetched user untouched by the fallback for non-master callers', async () => {
      const user = makeUser();
      const req = makeReq();
      const router = makeRouter(user);
      const filtered = { objectId: USER_ID, username: 'alice', protected: 'value' };
      rest.get.mockResolvedValue({ results: [filtered] });

      const result = await router.handleLogIn(req);

      expect(result.response).toBe(filtered);
      expect(result.response.sessionToken).toBe(SESSION_TOKEN);
    });
  });
});
