        body: { username: 'alice', password: 'secret', authData: { google: { id: 'other' } } },
      });
      const router = makeRouter(user);

      Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: 'another-user' }]);

      await expect(router.handleLogIn(req)).rejects.toMatchObject({
        code: Parse.Error.ACCOUNT_ALREADY_LINKED,
        message: 'this auth is already used',
      });

      expect(Auth.handleAuthDataValidation).not.toHaveBeenCalled();
      expect(RestWrite.createSession).not.toHaveBeenCalled();
      expect(maybeRunTrigger).not.toHaveBeenCalled();
      expect(req.config.database.update).not.toHaveBeenCalled();
    });

    it('does not persist authData when validation returns no changed fields', async () => {
