  describe('password expiry policy', () => {
    it('starts enforcing expiry by setting _password_changed_at when it is missing', async () => {
      const config = makeConfig({ passwordPolicy: { maxPasswordAge: 30 } });
      const user = makeUser();
      const req = makeReq({ config });
      const router = makeRouter(user);

      const result = await router.handleLogIn(req);

      expect(req.config.database.update).toHaveBeenCalledTimes(1);
      expect(req.config.database.update).toHaveBeenCalledWith(
        '_User',
        { username: 'alice' },
        {
          _password_changed_at: {
            __type: 'Date',
            iso: expect.any(String),
          },
        }
      );
      // Login continues despite the timestamp being reset.
      expect(RestWrite.createSession).toHaveBeenCalledTimes(1);
      expect(result.response.objectId).toBe(USER_ID);
    });

    it('rejects login when the stored password is expired', async () => {
      const config = makeConfig({ passwordPolicy: { maxPasswordAge: 1 } });
      const user = makeUser({
        _password_changed_at: { __type: 'Date', iso: '2000-01-01T00:00:00.000Z' },
      });
      const req = makeReq({ config });
      const router = makeRouter(user);

      await expect(router.handleLogIn(req)).rejects.toMatchObject({
        code: Parse.Error.OBJECT_NOT_FOUND,
        message: 'Your password has expired. Please reset your password.',
      });

      expect(req.config.database.update).not.toHaveBeenCalled();
      expect(maybeRunTrigger).not.toHaveBeenCalled();
      expect(RestWrite.createSession).not.toHaveBeenCalled();
    });

    it('allows login when a Parse-encoded password date is within the allowed age', async () => {
      const config = makeConfig({ passwordPolicy: { maxPasswordAge: 30 } });
      const user = makeUser({
        _password_changed_at: {
          __type: 'Date',
          iso: new Date(Date.now() - 60 * 60 * 1000).toISOString(),
        },
      });
      const req = makeReq({ config });
      const router = makeRouter(user);

      const result = await router.handleLogIn(req);

      expect(result.response.objectId).toBe(USER_ID);
      expect(req.config.database.update).not.toHaveBeenCalled();
      expect(RestWrite.createSession).toHaveBeenCalledTimes(1);
    });

    it('allows login when a plain Date password date is within the allowed age', async () => {
      const config = makeConfig({ passwordPolicy: { maxPasswordAge: 30 } });
      const user = makeUser({
        _password_changed_at: new Date(Date.now() - 60 * 60 * 1000),
      });
      const req = makeReq({ config });
      const router = makeRouter(user);

      await expect(router.handleLogIn(req)).resolves.toHaveProperty('response');
      expect(req.config.database.update).not.toHaveBeenCalled();
    });
  });

