    ...overrides,
  };
  return config;
}

function createReq(overrides = {}) {
  const headers = Object.assign({ host: 'localhost:1337' }, overrides.headers || {});
  const req = Object.assign(
    {
      originalUrl: '/parse/classes/Test',
      url: '/classes/Test',
      protocol: 'http',
      path: '/classes/Test',
      method: 'GET',
